        while end+2<len(hulu) and usage+hulu[end+1][1]<=K:
            usage += hulu[end+1][1]
            ones += hulu[end+2][1]
            end += 2

        output = ones+K

        # print([start,end,usage,ones])

        start += 2

        while start<len(hulu):
            ones -= hulu[start-2][1]
            usage -= hulu[start-1][1]
            if start>end:
                end = start
                ones = hulu[start][1]
                usage = 0
            while end+2<len(hulu) and usage+hulu[end+1][1]<=K:
                usage += hulu[end+1][1]
                ones += hulu[end+2][1]
                end += 2
