        return k >= max(
            (m + 26 * (count - 1) for m, count in list(c.items()) if m),
            default = 0)

class Solution:
    def maxSideLength(self, mat: List[List[int]], threshold: int) -> int:
        dp = [[0 for _ in range(len(mat[0]) + 1)]for r in range(len(mat) + 1)]

        for r in range(1, len(mat) + 1):
            for c in range(1, len(mat[r-1]) + 1):
                dp[r][c] += mat[r-1][c-1]
                if not r and not c:
                    continue
                elif not r:
                    dp[r][c] += dp[r][c-1]
                    continue
                elif not c:
                    dp[r][c] += dp[r-1][c]
                    continue
                dp[r][c] += dp[r][c-1] + dp[r-1][c] - dp[r-1][c-1]

        # print(dp)
        highest = -1
        for r in range(1, len(dp)):
            r0= r1 = r
            c0= c1 = 1
            while r1 < len(dp) and c1 < len(dp[0]):

                result = dp[r1][c1] + dp[r0-1][c0-1] - dp[r1][c0-1] - dp[r0-1][c1]

                # print(f'r0:{r0} r1:{r1} c0:{c0} c1:{c1} result:{result}')
                if result <= threshold:
                    highest = max(r1-r0, highest)
                    r1 += 1
                    c1 +=1
                else:
                    r1 -=1
                    c0 +=1
                r1 = max(r0+1,r1)
                c1 = max(c0+1,c1)

        return highest + 1

class Solution:
    def bagOfTokensScore(self, tokens: List[int], P: int) -> int:
        tokens = sorted(tokens)
        left = 0
        right = len(tokens) - 1
        points = 0

        if len(tokens) == 1:
            if tokens[0] <= P:
                return 1
        if len(tokens) == 0:
            return 0
        while left < right:

            if tokens[left] <= P:
                P -= tokens[left]
                left += 1
                points += 1

            elif tokens[left] > P and points > 0:
                P += tokens[right]
                points -= 1
                right -= 1


            elif points == 0 and tokens[left] > P:
                break
        if P >= tokens[left]:
            points += 1
        return points

from math import comb


class Solution:
    def getProbability(self, balls: List[int]) -> float:
        n = len(balls)
        s = sum(balls)
        s2 = s // 2

        @lru_cache(None)
        def count(index, delta, ca):
            if index == n: return 1 if delta == 0 and ca == s2 else 0
            total = sum([count(index + 1, delta, ca + x) * comb(balls[index], x) for x in range(1, balls[index])])
            total += count(index + 1, delta + 1, ca)
            total += count(index + 1, delta - 1, ca + balls[index])
            return total

        return count(0, 0, 0) / comb(s, s // 2)

class Solution:
     def flipLights(self, n, m):
         """
         :type n: int
         :type m: int
         :rtype: int
         """
         states = set()
         for op_odd in [0, 1]:
             for op_even in [0, 1]:
                 for op_third in [0, 1]:
                     op_all = m - op_odd - op_even - op_third
                     if op_all >= 0:
                         one = (op_odd + op_all + op_third) % 2
                         two = (op_even + op_all) % 2
                         three = op_odd % 2
                         four = (op_even + op_all + op_third) % 2
                         states.add((one, two, three, four)[:n])

         return len(states)

class Solution:
    def maxSumTwoNoOverlap(self, A: List[int], L: int, M: int) -> int:
        N = len(A)
        if L+M>N:
            return -1


        def findmax(L,M):    
            sL = [sum(A[:L])]
            for i in range(L,N-M):
                tmp = sL[-1]+A[i]-A[i-L]
                sL.append(tmp)
            sLmax = [sL[0]]
            for i in range(1,len(sL)):
                if sL[i]>sLmax[-1]:
                    sLmax.append(sL[i])
                else:
                    sLmax.append(sLmax[-1])

            sM = [sum(A[-M:])]
            for i in range(N-M-1,L-1,-1):
                tmp = sM[-1]+A[i]-A[i+M]
                sM.append(tmp)
            sMmax = [sM[0]]
            for i in range(1,len(sM)):
                if sM[i]>sMmax[-1]:
                    sMmax.append(sM[i])
                else:
                    sMmax.append(sMmax[-1])

            sMax = [sum(x) for x in zip(sLmax, sMmax[::-1])]
            m = max(sMax)

            return m

        if L == M:
            return findmax(L,M)
        else:
            return max(findmax(L,M), findmax(M,L))

class Solution:
    def minCost(self, n: int, cuts: List[int]) -> int:
        cuts.sort()
        from functools import lru_cache
        @lru_cache(None)
        def helper(i = 0, j = n):
            ans = math.inf
            for c in cuts:
                if c <= i: continue
                if c >= j: break
                ans = min(ans, j - i + helper(i, c) + helper(c, j))
            if ans == math.inf:
                return 0
            return ans
        return helper()

