from collections import defaultdict, deque
class Solution:
    def distinctEchoSubstrings(self, text: str) -> int:
        if all(x==text[0] for x in text):
            # handle worst case seperately
            return len(text)//2

        res = set()
        character_locations = defaultdict(lambda:deque())
        for i, c in enumerate(text):
            for j in character_locations[c]:
                if i + (i - j) > len(text): break

                # Use startswith to improve result slightly                    
                if text.startswith(text[i:i+i-j], j):
                    res.add(text[j:i+i-j])

            character_locations[c].appendleft(i)

        return len(res)

class Solution:
     def combinationSum4(self, nums, target):
         """
         :type nums: List[int]
         :type target: int
         :rtype: int
         """
         cache = {}
         def f(val):
           if val == target:
             return 1

           total = 0
           remain = target - val
           for num in nums:
             if num <= remain:
               k = val+num
               if k in cache:
                 total += cache[k]
               else:
                 cache[k] = f(val + num)
                 total += cache[k]
           return total

         return f(0)

