         def parseContent(src, i):
             j, res = i, False
             while i < len(src):
                 res, i = parseText(src, i)
                 if res:
                     continue

                 res, i = parseCDData(src, i)
                 if  res:
                     continue

                 res, i = parseTag(src, i)
                 if res:
                     continue

                 break

             return True, i

         def parseCDData(src, i):

             s = src.find('<![CDATA[', i)
             if s != i:
                 return False, i

             e = src.find(']]>', i)

             return (True, e+3) if e != -1 else (False, i)

         def parseText(src, i):
             j = i
             while i < len(src) and src[i] != '<':
                 i += 1

             return j != i, i

         def findtag(src, i):
             if src[i] != '<':
                 return "", i

             e = src.find('>', i+1)

             if e == -1 or e - i - 1 > 9 or e - i - 1 < 1:
                 return "", e

             s = 1
             while s < e - i and src[i+s].isupper():
                 s += 1

             return (src[i+1: e], e+1) if s >= e - i else ("", e)

         # start to check
         return parseTag(code, 0) == (True, len(code))

class Solution:
     def candy(self, ratings):
         """
         :type ratings: List[int]
         :rtype: int
         """

         if not ratings:
             return 0

         total, pre, decrease = 1, 1, 0
         for i in range(1, len(ratings)):
             if ratings[i] >= ratings[i-1]:
                 if decrease > 0:
                     total += (1+decrease)*decrease // 2
                     if pre <= decrease:
                         total += decrease+1-pre
                     decrease, pre = 0, 1
                 if ratings[i] == ratings[i-1]:
                     total += 1
                     pre = 1
                 else:
                     pre += 1
                     total += pre
             else:
                 decrease += 1

         if decrease > 0:
             total += (1 + decrease) * decrease // 2
             if pre <= decrease:
                 total += decrease + 1 - pre
         return total

import collections

class Solution:
    def shortestSubarray(self, A: List[int], K: int) -> int:
        cum_sum = 0
        queue = collections.deque([(-1, 0)])
        result = len(A) + 1
        for i, v in enumerate(A):
            cum_sum += v    
            if v > 0:
                # find any matches and remove them, since will never have a better match
                while queue and cum_sum - queue[0][1] >= K:
                    e = queue.popleft()
                    #print('remove candidate from start:', e)
                    result = min(result, i - e[0])
            else:
                # for negative numbers pop off any greater cum sums, which will never be a better target
                while queue and cum_sum <= queue[-1][1]:
                    e = queue.pop()
                    #print('remove lesser from end:', e)

            queue.append((i, cum_sum))
            #print(queue)            
        return result if result <= len(A) else -1

class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:

        flowersN = len(bloomDay)
        if flowersN < m*k:
            return -1

        def checkFlowers(x):
            count = 0
            gotFlowers = 0
            for num in bloomDay:
                if num <= x:
                    count += 1
                    if count == k:
                        gotFlowers += 1
                        count = 0
                else:
                    count = 0
            # print(gotFlowers, x, m)
            return gotFlowers >= m

        sortedDays = sorted(list(set(bloomDay)))
        l = 0
        r = len(sortedDays) - 1
        if checkFlowers(sortedDays[l]):
            return sortedDays[l]
        while l < r:
            mm = (l + r)//2
            if checkFlowers(sortedDays[mm]):
                r = mm
            else:
                l = mm+ 1
        return sortedDays[l]

class Solution:
    def numSub(self, s: str) -> int:
        # 10/6/20
        dic = collections.defaultdict(int)

        n = len(s)
        left, right = 0, 0
        while left < n:
            if s[left] == '1':
                right = left
                while right < n and s[right] == '1':
                    right += 1
                dic[right-left] += 1
                left = right
            else:
                left += 1

        total = 0
        for ones in dic:
            total = (total + (ones *(ones+1)) // 2 * dic[ones]) % (10**9 + 7)
        return total

class Solution:
    def longestPrefix(self, strn: str) -> str:
        max_prefs = [0]*len(strn)

        curr = 0
        for idx in range(1, len(strn)):
            while True:
                if curr == 0:
                    if strn[idx] == strn[0]:
                        curr = 1
                    max_prefs[idx] = curr
                    break
                else:
                    if strn[idx] == strn[curr]:
                        curr += 1
                        max_prefs[idx] = curr
                        break
                    else:
                        curr = max_prefs[curr-1]

        return strn[:max_prefs[-1]]

