class Solution:
    def maxProductPath(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        if (rows == 0):
            return -1

        cols = len(grid[0])
        if (cols == 0):
            return -1

        dp = [(1,1)] * cols
        for r, col in enumerate(grid):
            for c, item in enumerate(col):
                if (r == 0 and c == 0):
                    dp[c] = (item, item)
                elif (r == 0):
                    dp[c] = (dp[c-1][0] * item, dp[c-1][1]* item)
                elif (c == 0):
                    dp[c] = (dp[c][0] * item, dp[c][1]* item)
                else:
                    candidate_1 = dp[c-1][0] * item
                    candidate_2 = dp[c-1][1]* item
                    candidate_3 = dp[c][0] * item
                    candidate_4 = dp[c][1]* item

                    m = min(candidate_1, candidate_2, candidate_3, candidate_4)
                    M = max(candidate_1, candidate_2, candidate_3, candidate_4)

                    dp[c] = (m, M)

        if (dp[cols-1][1] >= 0):
            return dp[cols-1][1] % (10**9+7)
        else:
            return -1

class Solution:
     def isNumber(self, s):
         """
         :type s: str
         :rtype: bool
         """
         dot = False
         exp = False

         try:
             while s.startswith(' '):
                 s = s[1:]
             while s.endswith(' '):
                 s = s[:-1]
             if s.startswith('-') or s.startswith('+'):
                 s = s[1:]
         except IndexError:
             return False

         if s == '':
             return False

         if s.startswith('e'):
             return False
         if (s[-1] > '9' or s[-1] < '0') and s[-1] != '.':
             return False

         if s.startswith('.'):
             if len(s) == 1:
                 return False
             elif s[1] < '0' or s[1] > '9':
                 return False

         i = 0
         while i < len(s):
             if s[i] < '0' or s[i] > '9':
                 if s[i] == '.':
                     if not dot and not exp:
                         dot = True
                     else:
                         return False  # two dot in string or dot after e.
                 elif s[i] == 'e':
                     if not exp:
                         exp = True
                         if s[i+1] == '-' or s[i+1] == '+':
                             i = i + 1
                     else:
                         return False
                 else:
                     return False
             i = i + 1
         return True

class Solution:
    def angleClock(self, hour: int, minutes: int) -> float:
        hour_angle = hour*30+(minutes/12)*6
        if hour_angle > 360:
            hour_angle -= 360
        min_angle = (minutes/5)*30
        if min_angle > 360:
            min_angle -= 360

        diff = abs(hour_angle-min_angle)
        return diff if diff <= 360-diff else 360-diff

