        ACB
        X 1 2 3
        A 2 0 0
        B 0 1 1
        C 0 1 1
        '''

        mem = {}
        for vote in votes:
            for i in range(len(vote)):
                team = vote[i]
                if team not in mem:
                    mem[team] = [0 for _ in range(len(vote))]
                mem[team][i] += 1

