 while l <= r: 
  mid = l + (r - l)//2; 
  if arr[mid] == x: 
   return mid+1 
  elif arr[mid] < x: 
   l = mid + 1
  else: 
   r = mid - 1
 if mid!=len(arr):
  if arr[mid]<x:
   return mid+1
 return mid
