	mod = 10**9 + 7
	if a < b:
		return 0
	if a == 1:
		return 1
	if b < a/2:
		b = a - b
	temp = 1
	for i in range(b + 1,a + 1):
		temp = (temp * i%mod)%mod
	denom = modin(math.factorial(a-b),mod)
	# print denom
	return (temp%mod * denom%mod)%mod
