        isolbelow = True
        lastp = ps[0]

        while not valsdone and n>=k:
            if n == k:
                lo = x+d+1 # put out of range
            else:
            # find best maxfill (before val support)
                lo = 1
                hi = x+1
                while hi-lo>1:
                    md = (hi+lo)//2
                    v = (x-md+1) + ctlt(ps,md)
                    if v<n:
