def check_intersect(rectas):
    u=rectas[-1]
    ux=[u[0][0],u[1][0]]
    ux.sort()
    uy=[u[0][1],u[1][1]]
    uy.sort()

    oriU = ""
    if ux[0] == ux[1]: oriU = "V"
    if uy[0] == uy[1]: oriU = "H"

    for r in rectas[:-2]:
        rx=[r[0][0],r[1][0]]
        rx.sort()
        ry=[r[0][1],r[1][1]]
        ry.sort()

        oriR = ""
        if rx[0] == rx[1]: oriR = "V"
        if ry[0] == ry[1]: oriR = "H"

        if oriU==oriR: 
            if oriU == "V" and ux[0]==rx[0]:
                if ry[0] <= uy[0] <= ry[1] or ry[0] <= uy[1] <= ry[1] :
                    return True
                if uy[0] < ry[0] and uy[1] > ry[1]:
                    return True 

            if oriU =="H" and uy[0]==ry[0]:
                if rx[0] <= ux[0] <= rx[1] or rx[0] <= ux[1] <= rx[1] :
                    return True
                if ux[0] < rx[0] and ux[1] > rx[1]:
                    return True 
        elif oriU =="V":
            if uy[0]<=ry[0]<=uy[1]:
                if rx[0] < ux[0] and rx[1] > ux[0]:
                    return True
        elif oriU =="H":
            if ux[0]<=rx[0]<=ux[1]:
                if ry[0] < uy[0] and ry[1] > uy[0]:
                    return True  
        else:
            return False

def calc_area(camino):
