def find_prime_kPerm(n, k):
    sieve = n // 2 * [True]
    for i in range(3, int(n ** .5) + 1, 2):
        if sieve[i // 2]:
            sieve[i*i // 2 :: i] = ((n - i*i - 1) // (2*i) + 1) * [False]
    cycles = {}
    for i in range(1, n // 2):
        if sieve[i]:
            cycles.setdefault(tuple(sorted(str(2*i + 1))), set()).add(2*i + 1)
    k_perms = [min(cycle) for cycle in cycles.values() if len(cycle) == k + 1]
    return [len(k_perms), min(k_perms, default=0), max(k_perms, default=0)]

from fractions import gcd

def min_price(nums):
    nums.sort()
    ns = [0] + [float('inf')] * (nums[0] - 1)
    for c in nums[1:]:
        d = gcd(nums[0], c)
        for r in range(d):
            n = min(ns[r::d], default=float('inf'))
            if n < float('inf'):
                for j in range(nums[0] // d):
                    n += c
                    p = n % nums[0]
                    ns[p] = n = min(n, ns[p])
    max_ = max(ns) or 1
    return max_ - nums[0] + 1 if max_ < float('inf') else -1

