        if len(shifts) >= 2:
            for i in range(len(shifts) - 2, -1, -1):
                shifts[i] += shifts[i + 1]
                shifts[i] = shifts[i] % 26

        # shift characters
        shifted_chars = []

        for i in range(len(S)):
