class Solution:
    def longestZigZag(self, root: TreeNode) -> int:
        if root == None:
            return None

        maxlength = 0
        stack = collections.deque()
        if root.left:
            stack.append((1, 1, root.left))
        if root.right:
            stack.append((1, 0, root.right))
        while stack:
            length, isleft, node = stack.pop()
            if isleft:
                if node.right:
                    stack.append((length + 1, 0, node.right))
                else:
                    maxlength = max(maxlength, length)
                if node.left:
                    stack.append((1, 1, node.left))
            else:
                if node.left:
                    stack.append((length + 1, 1, node.left))
                else:
                    maxlength = max(maxlength, length)

                if node.right:
                    stack.append((1, 0, node.right))

        return maxlength

class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        arr.sort()
        i, j = 0, len(arr) - 1
        median = arr[(len(arr) - 1) // 2]
        while len(arr) + i - j <= k:
            if median - arr[i] > arr[j] - median:
                i = i + 1
            else:
                j = j - 1
        return arr[:i] + arr[j + 1:]

class Solution:
  def frogPosition(self, n: int, edges: List[List[int]], t: int, target: int) -> float:
    tree = dict()
    for i, j in edges:
      if i > j: i, j = j, i
      tree.setdefault(i - 1, []).append(j - 1)

    queue, time = [(0, 1)], 0  # node-prob
    while queue and time <= t:  # bfs 
      tmp = []
      for node, prob in queue:
        if node == target - 1: return 0 if time < t and node in tree else prob
        for n in tree.get(node, []): tmp.append((n, prob / len(tree[node])))
      queue, time = tmp, time + 1
    return 0

