         if l<2:
             return asteroids
         ans=[]
         stack=[]
         for a in asteroids:
             if a>0:
                 stack.append(a)
             else:
                 a=-a
                 equal_flag=False
                 while stack:
                     cur=stack.pop()                  
                     if cur==a:
                         equal_flag=True
                         break
                     elif cur>a:
                         stack.append(cur)
                         break              
                 if equal_flag:
                     continue            
                 if not stack:
                     ans.append(-a)
         return ans+stack

class StreamChecker:

    def __init__(self, words: List[str]):
        #reverse trie
        self.trie = {}
        self.stream = deque([])

        for word in set(words):
            node = self.trie       
            for ch in word[::-1]:
                if not ch in node:
                    node[ch] = {}
                node = node[ch]
            node['$'] = word

    def query(self, letter: str) -> bool:
        self.stream.appendleft(letter)

        node = self.trie
        for ch in self.stream:
            if '$' in node:
                return True
            if not ch in node:
                return False
            node = node[ch]
        return '$' in node


