class Solution:
    def intervalIntersection(self, A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
        result = []
        i = j = 0

        while i < len(A) and j < len(B):
            low = max(A[i][0], B[j][0])
            high = min(A[i][1], B[j][1])

            if low <= high:
                result.append([low, high])

            if A[i][1] > B[j][1]:
                j += 1
            elif A[i][1] < B[j][1]:
                i += 1
            else:
                i += 1
                j += 1

        return result

class Solution:
    def maxEqualRowsAfterFlips(self, matrix: List[List[int]]) -> int:
        dict_ = {}
        for row in matrix:
            curr_tuple = tuple(row)
            dict_[curr_tuple] = 1 + dict_.get(curr_tuple,0)
        visited = set()
        max_same = 0
        for row in matrix:
            curr_tuple = tuple(row)
            if curr_tuple in visited:
                continue
            visited.add(curr_tuple)
            inverse = [1] * len(row)
            for i in range (len(row)):
                if row[i]:
                    inverse[i] = 0
            curr_inv = tuple(inverse)
            visited.add(curr_inv)
            curr_sum = 0
            curr_sum = dict_[curr_tuple]
            if curr_inv in dict_:
                curr_sum += dict_[curr_inv]
            if curr_sum > max_same:
                max_same = curr_sum
        return max_same

class Solution:
    def wordSubsets(self, A: List[str], B: List[str]) -> List[str]:
        s = set(A)
        letters_required = {}
        for i in B:
            for j in i:
                count = i.count(j)
                if j not in letters_required or count > letters_required[j]:
                    letters_required[j] = count

        for i in A:
            for j in letters_required:
                if i.count(j) < letters_required[j]:
                    s.remove(i)
                    break
        return list(s)

