class Solution:
     def shoppingOffers(self, price, special, needs):
         """
         :type price: List[int]
         :type special: List[List[int]]
         :type needs: List[int]
         :rtype: int
         """
         def dfs(curr, special, needs):
             p=curr+sum(p*needs[i] for i,p in enumerate(price))
             for si in range(len(special)):
                 s = special[si]
                 if all(n>=s[i] for i,n in enumerate(needs)):
                     p=min(p, dfs(curr+s[-1], special[si:], [n-s[i] for i,n in enumerate(needs)]))
                 # else: p=min(p, dfs(curr, special[si+1:], needs))
             return p
         return dfs(0, special, needs)

class Solution:
    def maxNumEdgesToRemove(self, n: int, edges: List[List[int]]) -> int:
        if len(edges) == 0:
            return 0 if n == 0 else -1
        p = [i for i in range(n)]
        def getP(ind):
            nonlocal p
            if p[ind] == ind:
                return ind
            else:
                res = getP(p[ind])
                p[ind] = res
                return res
        cnt = 0
        for t,u,v in edges:
            if t == 3:
                pu,pv = getP(u-1), getP(v-1)
                if pu != pv:
                    p[pv] = pu
                    cnt += 1
        if cnt != (n - 1):
            pa = list(p)
            for t,u,v in edges:
                if t == 1:
                    pu,pv = getP(u-1), getP(v-1)
                    if pu != pv:
                        p[pv] = pu
                        cnt += 1
            targetP = getP(0)
            for v in range(n):
                if getP(v) != targetP:
                    return -1
            p = pa
            for t,u,v in edges:
                if t == 2:
                    pu,pv = getP(u-1), getP(v-1)
                    if pu != pv:
                        p[pv] = pu
                        cnt += 1
            targetP = getP(0)
            for v in range(n):
                if getP(v) != targetP:
                    return -1
        return len(edges) - cnt

class Solution:
    def numSubmat(self, mat: List[List[int]]) -> int:
        n, m = len(mat), len(mat[0])
        heights = [0] * m
        res = 0
        for i in range(0, n):
            stack = []
            count = 0
            for j in range(0, m):
                if mat[i][j] == 1:
                    heights[j] += 1
                else:
                    heights[j] = 0
            for index, height in enumerate(heights):
                while stack and height < heights[stack[-1]]:
                    curr = stack.pop()
                    left = stack[-1] if stack else -1
                    count -= (heights[curr] - height) * (curr - left)
                count += height
                res += count
                stack.append(index)
        return res

class Solution(object):
    def splitIntoFibonacci(self, S):
        \"\"\"
        :type S: str
        :rtype: List[int]
        \"\"\"
        n = len(S)
        for i in range(1, 11):
            for j in range(1, 11):
                if i + j >= n:
                    break
                L = self.buildFibo(S, i, j)
                if L:
                    return L
        return []

    def buildFibo(self, s, i, j):
        a = s[:i]
        b = s[i:i+j]
        if a[0] == '0' and i > 1:
            return []
        if b[0] == '0' and j > 1:
            return []

        offset = i + j
        n = len(s)
        x, y = int(a), int(b)
        arr = [x, y]
        while offset < n:
            z = x + y
            if z > 2147483647:
                return []

            c = str(z)
            k = len(c)
            if offset + k > n or s[offset:offset+k] != c:
                return []
            offset += k
            arr.append(z)
            x, y = y, z
        return arr

class Solution:
    def removeSubfolders(self, folder):

        folders = folder

        folders.sort()
        output = []
        parent = ' '

        for folder in folders:
            if not folder.startswith(parent):
                output.append(folder)
                parent = folder + '/'

        return output

class Solution:
     def nearestPalindromic(self, num):
         """
         :type n: str
         :rtype: str
         """
         K = len(num)
         candidates = set([10**K + 1, 10**(K-1) - 1])
         Prefix = int(num[:(K+1)//2])

         for start in map(str, [Prefix-1, Prefix, Prefix+1]):
             candidates.add(start + [start, start[:-1]][K & 1][::-1])

         candidates.discard(num)

         return str(min(candidates, key=lambda x: (abs(int(x) - int(num)), int(x))))

