 class Solution:
     def postorderTraversal(self, root):
         """
         :type root: TreeNode
         :rtype: List[int]
         """
         if root==None:
             return []
         stack=[]
         stack_left=[1]
         while stack_left!=[]:
             stack.append(root.val)
             if root.left!=None and root.right==None:
                 root=root.left
             elif root.left==None and root.right!=None:
                 root=root.right
             elif root.left!=None and root.right!=None:
                 stack_left.append(root.left)
                 root=root.right
             else:
                 if stack_left==[1]:
                     stack_left=[]
                 else:
                     root=stack_left.pop()
         #print(stack)
         stack.reverse()
         return stack

class CustomStack:

    def __init__(self, maxSize: int):
        self.stack = []
        self.add = []
        self.limit = maxSize

    def push(self, x: int) -> None:
        if len(self.stack) < self.limit:
            self.stack.append(x)
            self.add.append(0)

    def pop(self) -> int:
        if len(self.stack) == 0:
            return -1
        result = self.stack.pop()
        left = self.add.pop()
        if len(self.add) > 0:
            self.add[-1] += left
        return result + left

    def increment(self, k: int, val: int) -> None:
        if len(self.stack) > 0:
            if k > len(self.stack):
                self.add[-1] += val
                return
            self.add[k-1] += val



