memo_ff={}
def powpoly(x,t):
  ret=[1]+[0]*( len(x)-1 )
  n=len(x)
  for _ in range(t):
    ret2=[0 for _ in range(n)]
    for i in range(n):
      for j in range(n):
        if i+j<n:
          ret2[i+j]+=ret[i]*x[j]
    ret=ret2
  return ret

def ing(x):
  n=len(x)
  assert x[0]==0
  ret=[0 for _ in range(n)]
  for t in range(0,n):
    ret2=powpoly(x,t)
    for i in range(n):
      ret[i]+=fr*ret2[i]/fact(t)
  return ret


def ff(Y):
  if Y in memo_ff:
    return memo_ff[Y]
  t=Y[0]
  if t==0:
    n=Y[1]
    ret=0
    for (v,e) in sve:
      if v+e>n or v==0:continue
      val=sve[(v,e)]
      for l1 in range(n-v+1):
        l2=n-v-l1
        p1=ff((2,l1,e))
        p2=ff((3,l2,v))
        a = fr * val * fact(n-1) / fact(v-1) / fact(l1) / fact(l2) * p1 * p2 / fact(e)
        ret += a
  elif t==1:
    n=Y[1]
    ret=0
    for (v,e) in sve:
