from functools import reduce

def modpow(a, n, m):
    if n == 0:
        return 1
    tmp = modpow(a, n // 2, m)
    if n % 2 == 0:
        return tmp * tmp % m
    else:
        return tmp * tmp * a % m

def modinv(a, m):
    return modpow(a, m - 2, m)

