            rev_d = {sum(key): [] for key in list(d.values())}
            for x in d:
                rev_d[d[x][0] + d[x][1]] += [d[x]]

            for x in rev_d:
                rev_d[x].sort(key=lambda item:item[1])

            # print(rev_d)

            cur = max(rev_d)
            cnt = max(rev_d)
            nb_candies = 0
            given_away = 0
            while 1:
                if cnt == 0 or cur == 0:
