        char_map = {char: i for i, char in enumerate(order)}
        for j in range(1, len(words)):
            prev, curr = words[j - 1], words[j]

            k = 0
            while k < min(len(prev), len(curr)):
                if prev[k] == curr[k]:
                    k += 1
