    ALL = (pow(2, y - 1, MOD)) % MOD

    k = 2
    while k*k <= y:
        if y % k == 0:
            if k*k != y:
                ALL -= find(y//k)
                ALL -= find(k)
            else:
                ALL -= find(k)
        k += 1
        #print(k, ALL)

    if y != 1:
        ALL -= 1

    memo2[y] = ALL % MOD
    return ALL % MOD

