def median(a):
    if len(a) == 0:
        return 0
    if len(a) % 2 == 1:
        return a[len(a) // 2]
    else:
        return (a[len(a) // 2] + a[(len(a) // 2) - 1]) // 2


def profit(a, old_val):
    a.sort()
    med = median(a)
    sum_old = 0
    sum_new = 0
    for i in a:
        sum_old += abs(i - old_val)
        sum_new += abs(i - med)
    return sum_old - sum_new

