M = 10 ** 9 + 7

def inv(x):
    return pow(x, M - 2, M)

def binomial(n, k):
    if 0 <= k <= n:
        ntok = 1
        ktok = 1
        for t in range(1, min(k, n - k) + 1):
            ntok *= n
            ktok *= t
            n -= 1
            ntok %= M
            ktok %= M
        return (ntok * inv(ktok))%M
    else:
        return 0

