def LIS(lis , end):

    seq = []

    for c in lis:
        ind = bisect.bisect_right(seq,c)

        if ind == len(seq):
            seq.append(c)
        else:
            if ind != 0:
                seq[ind] = c

    return bisect.bisect_right(seq,end)

