			continue
		opt, secondOpt = 0, 0
		total = 1
		for j in g[i]:
			val, size = 0, 0
			if par[j] == i:
				val = cnt[j]
				size = sub[j]
			else:
				val = up[i]
				size = n - sub[i]
			if val == size:
				total += val
			else:
				if opt < val:
					opt, secondOpt = val, opt
				elif secondOpt < val:
					secondOpt = val

		for j in g[i]:
			if par[j] == i:
				up[j] = total
				add = opt
				if sub[j] == cnt[j]:
					up[j] -= cnt[j]
				elif cnt[j] == opt:
					add = secondOpt
				up[j] += add
	for i in range(n):
