def accumulate2d(X):
    N = len(X)
    M = len(X[0])

    for i in range(0, N):
        for j in range(1, M):
            X[i][j] += X[i][j-1]

    for j in range(0, M):
        for i in range(1, N):
            X[i][j] += X[i-1][j]

    return X

