    for l,r in D:
        if l > r:
            inc.append((l, r))
        else:
            dec.append((l, r))

    inc.sort(key=lambda x:x[1])
    dec.sort(key=lambda x:-x[1])

    D = inc + dec

    for i, (l,r) in enumerate(D):
        L -= r
        if L < 0:
            print('No')
            return
        L += l

    if L == R:
        print('Yes')
