class Solution:
     def uniquePathsWithObstacles(self, obstacleGrid):
         """
         :type obstacleGrid: List[List[int]]
         :rtype: int
         """
         m = len(obstacleGrid) #row
         n = len(obstacleGrid[0]) #col
         path = [[0 for j in range(n)] for i in range(m)]
         for i in range(m):
             if obstacleGrid[i][0] == 0:
                 path[i][0] = 1
             else:
                 break
         for i in range(n):
             if obstacleGrid[0][i] == 0:
                 path[0][i] = 1
             else:
                 break
         for i in range(1,m):
             for j in range(1,n):
                 if obstacleGrid[i][j] != 1:
                     path[i][j] = path[i-1][j] + path[i][j-1]
                 else:
                     path[i][j] = 0
         return path[m-1][n-1]

class Solution:
     def minPathSum(self, grid):
         """
         :type grid: List[List[int]]
         :rtype: int
         """
         m, n = len(grid), len(grid[0])
         dp = [0] + [float('inf')] * (n-1)
         for i in range(m):
             dp[0] = dp[0] + grid[i][0]
             for j in range(1, n):
                 dp[j] = min(dp[j], dp[j-1]) + grid[i][j]
         return dp[-1]

class Solution:
     def calculateMinimumHP(self, dungeon):
         """
         :type dungeon: List[List[int]]
         :rtype: int
         """
         '''
         逆回，当是小于等于0时，是相反数+1.   dp为到当前i,j只要需要的点数， 最小为1，保证 活着

         r,  c   r   ,c+1
         r+1,c   r+1,c+1

         r,c处至少的点数 - r,c处惩罚点数  是  其下面和右面最少需要的点数，  也就是第33行

         '''
         row = len(dungeon)
         col = len(dungeon[0])
         dp = [[0 for  c in range(col)] for r in range(row)]
         if dungeon[-1][-1] <= 0:
             dp[-1][-1] = -dungeon[-1][-1] + 1
         else:
             dp[-1][-1] = 1
         for r in range(row-2,-1,-1):
             dp[r][-1] = dp[r+1][-1]  - dungeon[r][-1]
             if dp[r][-1] <= 0:
                 dp[r][-1] = 1
         for c in range(col-2,-1,-1):
             dp[-1][c] = dp[-1][c+1]  - dungeon[-1][c]
             if dp[-1][c] <= 0:
                 dp[-1][c] = 1
         for r in range(row-2,-1,-1):
             for c in range(col-2,-1,-1):
                 dp[r][c] = min(dp[r+1][c],dp[r][c+1]) - dungeon[r][c]
                 if dp[r][c] <= 0:
                     dp[r][c] = 1
         return dp[0][0]

