class Solution(object):
     def findSubstring(self, s, words):
         """
         :type s: str
         :type words: List[str]
         :rtype: List[int]
         """
         if not s or words==[]:
             return []
         lenstr=len(s)
         lenword=len(words[0])
         lensubstr=len(words)*lenword
         times={}
         for word in words:
             if word in times:
                 times[word]+=1
             else:
                 times[word]=1
         ans=[]
         for i in range(min(lenword,lenstr-lensubstr+1)):
             self.findAnswer(i,lenstr,lenword,lensubstr,s,times,ans)
         return ans
     def findAnswer(self,strstart,lenstr,lenword,lensubstr,s,times,ans):
         wordstart=strstart
         curr={}
         while strstart+lensubstr<=lenstr:
             word=s[wordstart:wordstart+lenword]
             wordstart+=lenword
             if word not in times:
                 strstart=wordstart
                 curr.clear()
             else:
                 if word in curr:
                     curr[word]+=1
                 else:
                     curr[word]=1
                 while curr[word]>times[word]:
                     curr[s[strstart:strstart+lenword]]-=1
                     strstart+=lenword
                 if wordstart-strstart==lensubstr:
                     ans.append(strstart)

class Solution:
     def compareVersion(self, version1, version2):
         """
         :type version1: str
         :type version2: str
         :rtype: int
         """
         while version1 and version2:
             result1 = version1.split('.', 1)
             if len(result1) == 2:
                 digit1, version1 = result1[0], result1[1]
             else:
                 digit1 = result1[0]
                 version1 = ""
             result2 = version2.split('.', 1)
             if len(result2) == 2:
                 digit2, version2 = result2[0], result2[1]
             else:
                 digit2 = result2[0]
                 version2 = ""
             if int(digit1) > int(digit2):
                 return 1
             elif int(digit1) < int(digit2):
                 return -1

         if version1 and sum(map(lambda x: int(x), version1.split('.'))) != 0:
             return 1
         if version2 and sum(map(lambda x: int(x), version2.split('.'))) != 0:
             return -1
         return 0

class Solution:
     def searchRange(self, nums, target):
         """
         :type nums: List[int]
         :type target: int
         :rtype: List[int]
         """
         start = self.firstGreaterEqaul(nums, target)
         if start==len(nums) or nums[start]!=target:
             return [-1, -1]
         return [start, self.firstGreaterEqaul(nums, target+1)-1]
     def firstGreaterEqaul(self, nums, target):
         lo, hi = 0, len(nums)
         while lo<hi:
             mid = (hi+lo)//2
             if nums[mid]<target:
                 lo = mid + 1
             else:
                 hi = mid
         return lo

