    while j <= n:
        if d > k:
            d -= t[i]
            i += 1
        elif d == k:
            if t[i] and (j == n or t[j]): s += 1
            else:
                a, b = i - 1, j - 1
                while j < n and t[j] == 0: j += 1
                while t[i] == 0: i += 1
