def solve(a,l,r,k):
    out = sorted(a[:l]+a[r:],reverse=True)
    inside = sorted(a[l:r])
    cur = sum(a[l:r])
    for i in range(min(k,len(inside),len(out))):
        if out[i] > inside[i]:
            cur += out[i]-inside[i]
        else:
            break
    return cur

