        return ans

    def __imul__(self, other):
        self = self * other
        return self

    def __pow__(self, n):
        if n == 0:
            ans = Matrix(self.n, self.n)
            for i in range(self.n):
                ans.arr[i][i] = 1
            return ans
        elif n & 1 == 1:
            return self * (self ** (n - 1))
        else:
            t = self ** (n >> 1)
            return t * t

    def __ipow__(self, n):
        self = self ** n
        return self

    def __eq__(self, other):
        if self.n != other.n or self.m != other.m:
            return False
        for i in range(self.n):
            for j in range(self.m):
                if self.arr[i][j] != other.arr[i][j]:
                    return False
        return True


