class Solution:

    def makesquare(self, nums):
        """
         :type nums: List[int]
         :rtype: bool
         """
        if len(nums) < 4:
            return False
        length = sum(nums)
        if length % 4:
            return False
        length = int(length / 4)
        nums.sort(reverse=True)
        if length < nums[0]:
            return False
        elif length == nums[0]:
            stack = list([(set([0]), 1, length, 1)])
        else:
            stack = list([(set([0]), 1, length - nums[0], 2)])
        while stack:
            usedSet, startIndex, target, remainRounds = stack.pop()
            for i in range(len(nums) - 1, startIndex - 1, -1):
                if i in usedSet:
                    continue
                num = nums[i]
                if num < target and i + 1 < len(nums):
                    stack.append((usedSet | {i}, i + 1, target - num, remainRounds))
                elif num == target:
                    if remainRounds == 0:
                        return True
                    else:
                        stack.append((usedSet | {i}, 1, length, remainRounds - 1))
        return False

import sys

def dp(s1, s2, i, j, mem):
    if (i, j) in mem:
        return mem[i, j]
    elif i >= len(s1) and j >= len(s2):
        res = ''
    elif i >= len(s1):
        res = s2[j:]
    elif j >= len(s2):
        res = s1[i:]
    elif s1[i] == s2[j]:
        res = s1[i] + dp(s1, s2, i + 1, j + 2, mem)
    else:
        left = s1[i] + dp(s1, s2, i + 1, j, mem)
        right = s2[j] + dp(s1, s2, i, j + 1, mem)
        if len(left) < len(right):
            res = left
        else:
            res = right
    mem[i, j] = res
    return res

