class Solution:

    def superEggDrop(self, K: int, N: int) -> int:

        def f(t):
            a = 0
            r = 1
            for i in range(1, K + 1):
                r *= t - i + 1
                r //= i
                a += r
                if a >= N:
                    break
            return a
        l, h = (1, N)
        while l < h:
            m = (l + h) // 2
            if f(m) < N:
                l = m + 1
            else:
                h = m
        return l

class Solution:

    def preferences_to_scores(self, preferences):
        scores = {}
        for u, up in enumerate(preferences):
            for s, v in enumerate(up):
                scores[u, v] = s
        return scores

    def unhappy_friends(self, scores, a, b):
        ret = set()
        for ai, aa in enumerate(a):
            af = a[1 - ai]
            for bi, bb in enumerate(b):
                bf = b[2 - bi]
                if scores[aa, bb] < scores[aa, af] and scores[bb, aa] < scores[bb, bf]:
                    ret.add(aa)
                    ret.add(bb)
        return ret

    def unhappyFriends(self, n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
        scores = self.preferences_to_scores(preferences)
        ret = set()
        for i, a in enumerate(pairs):
            for j in range(i):
                b = pairs[j]
                ret |= self.unhappy_friends(scores, a, b)
        return len(ret)

class Solution:

    def canPartitionKSubsets(self, nums, k):
        """
         :type nums: List[int]
         :type k: int
         :rtype: bool
         """
        target, rem = divmod(sum(nums), k)
        if rem or max(nums) > target:
            return False
        n = len(nums)
        seen = [0] * n
        nums.sort(reverse=True)

        def dfs(k, index, current_sum):
            if k == 1:
                return True
            if current_sum == target:
                return dfs(k - 1, 0, 0)
            for i in range(index, n):
                if not seen[i] and current_sum + nums[i] <= target:
                    seen[i] = 1
                    if dfs(k, i + 1, current_sum + nums[i]):
                        return True
                    seen[i] = 0
            return False
        return dfs(k, 0, 0)

class Solution:

    def containsNearbyAlmostDuplicate(self, nums, k, t):
        """
         :type nums: List[int]
         :type k: int
         :type t: int
         :rtype: bool
         """
        if len(nums) < 2 or k <= 0 or t < 0:
            return False
        if t == 0:
            visited = set()
            for i, n in enumerate(nums):
                if n in visited:
                    return True
                visited.add(n)
                if i >= k:
                    visited.remove(nums[i - k])
            return False
        bucket = {}
        for i, n in enumerate(nums):
            b = n // t
            if b in bucket:
                return True
            if b + 1 in bucket and abs(bucket[b + 1] - n) <= t:
                return True
            if b - 1 in bucket and abs(bucket[b - 1] - n) <= t:
                return True
            bucket[b] = n
            if i >= k:
                del bucket[nums[i - k] // t]
        return False

class Solution:

    def orderlyQueue(self, S: str, K: int) -> str:
        if K >= 2:
            return ''.join(sorted(S))
        length = len(S)
        S = S + S
        i, j, k = (0, 1, 0)
        while j + k < len(S) and k < length:
            if S[i + k] == S[j + k]:
                k += 1
                continue
            elif S[i + k] < S[j + k]:
                j = j + k + 2
            else:
                i = max(i + k + 1, j)
                j = i + 1
            k = 0
        return S[i:i + length]

