class Solution:

    def fractionToDecimal(self, numerator, denominator):
        """
         :type numerator: int
         :type denominator: int
         :rtype: str
         """
        if numerator * denominator < 0:
            add_negative = True
        else:
            add_negative = False
        numerator, denominator = (abs(numerator), abs(denominator))
        integer_part = int(numerator // denominator)
        new_numerator = numerator - integer_part * denominator
        dict_residuals = {}
        digit_location = 0
        digit_array = []
        residual = new_numerator
        if residual == 0:
            if add_negative:
                return '-' + str(integer_part)
            else:
                return str(integer_part)
        is_repeating = True
        dict_residuals[residual] = 0
        while True:
            new_digit, residual = self.single_digit(residual, denominator)
            digit_location += 1
            if residual == 0:
                dict_residuals[residual] = digit_location
                digit_array.append(str(new_digit))
                is_repeating = False
                break
            elif residual in dict_residuals.keys():
                digit_array.append(str(new_digit))
                is_repeating = True
                break
            else:
                dict_residuals[residual] = digit_location
                digit_array.append(str(new_digit))
        if not is_repeating:
            result = str(integer_part) + '.' + ''.join(digit_array)
        else:
            loc = dict_residuals[residual]
            result = str(integer_part) + '.' + ''.join(digit_array[0:loc]) + '(' + ''.join(digit_array[loc:]) + ')'
        if add_negative:
            return '-' + result
        else:
            return result

    def single_digit(self, value, denominator):
        return (int(10 * value // denominator), 10 * value % denominator)

class Solution:

    def maxScoreWords(self, words: List[str], letters: List[str], score: List[int]) -> int:
        let = Counter(letters)
        sc = {}
        for i in range(26):
            sc[chr(i + ord('a'))] = score[i]
        word = {}
        for w in words:
            word[w] = Counter(w)
        self.ans = 0
        used = []

        def run(x, cur, let):
            if x == len(words):
                return
            for i in range(x, len(words)):
                if i not in used:
                    tmp = dict(let)
                    bx = True
                    d = 0
                    for k, v in word[words[i]].items():
                        if k not in let:
                            bx = False
                            break
                        let[k] -= v
                        d += sc[k] * v
                        if let[k] < 0:
                            bx = False
                            break
                    if bx:
                        used.append(i)
                        run(i + 1, cur + d, let)
                        if cur + d > self.ans:
                            self.ans = max(self.ans, cur + d)
                        used.pop()
                        let = tmp
                    let = tmp
        run(0, 0, let)
        return self.ans

class Solution:

    def findKthBit(self, n: int, k: int) -> str:
        i = n - 1
        invert = False
        while i > 0:
            half_len = (2 ** (i + 1) - 1) // 2
            if k == half_len + 1:
                return '1' if not invert else '0'
            if k > half_len:
                k = half_len - (k - half_len - 1) + 2
                invert = not invert
            i -= 1
        return '1' if invert else '0'

class Solution:

    def rob(self, nums):
        """
         :type nums: List[int]
         :rtype: int
         """
        if not nums:
            return 0
        if len(nums) == 1:
            return nums[0]
        return max(self.helper(nums[1:]), self.helper(nums[:-1]))

    def helper(self, nums):
        now = prev = 0
        for nxt in nums:
            now, prev = (max(nxt - prev, now), now)
        return now

