def bin_expo(x, n, p):
    if n == 0:
        return 1
    elif n == 1:
        return x % p
    else:
        temp = bin_expo(x, n // 2, p)
        temp = temp * temp % p
        if n % 2 == 0:
            return temp
        else:
            return x % p * temp % p
