    f[0], f[1] = (1, 1)
    for i in range(1, 51):
        f[i] = f[i - 1] * i % mod
    return f

def gcd110():
    gc = [[0] * 111 for i in range(111)]
    for i in range(111):
        for j in range(111):
            gc[i][j] = gcd(i, j)
    return gc
