def rule_asc(n, l):
    a, k = ([0 for i in range(n + 1)], 1)
    a[1] = n
    while k != 0:
        x, y = (a[k - 1] + 1, a[k] - 1)
        k -= 1
        while x <= y and k < l - 1:
            a[k], y = (x, y - x)
            k += 1
        a[k] = x + y
        yield a[:k + 1]

def niceness(s):
    t = 0
    for i in range(len(s)):
        for j in range(i + 1, len(s)):
            t = (t + gcds[s[i]][s[j]]) % mod
    return t

def permcount(s, c):
    f, p = ([s.count(x) for x in set(s)], factorials[c])
    for e in f:
        p = p * pow(factorials[e], mod - 2, mod) % mod
    return p

