                    self.pngs[x, y] = {'h': 10, 'atk': 3}
                elif c == 'E':
                    self.pngs[x, y] = {'h': 1, 'atk': 2}
                elif c == 'M':
                    self.pngs['M'] = {'coins': 3}

    def state(self):
        return (self.field, self.h, self.atk, self.d, sorted(self.bag))

    def rotate(self, c):
        self.dx, self.dy = self.DIRS[c]
        self.c = self.field[self.x][self.y] = c

    def move(self):
        self.field[self.x][self.y] = ' '
        self.x += self.dx
        self.y += self.dy
        c = self.field[self.x][self.y]
        assert c not in '#ED-|M' and self.x >= 0 and (self.y >= 0)
        if c != ' ':
            self.takeThis(c)
        self.field[self.x][self.y] = self.c

    def checkAhead(self, what):
        x, y = (self.x + self.dx, self.y + self.dy)
        assert self.field[x][y] in what
        return (x, y)

    def takeThis(self, c):
        if c not in 'SX':
            self.bag.append(c)
        if c == 'S':
            self.d += 1
        elif c == 'X':
            self.atk += 1

    def use(self, c):
        self.bag.remove(c)
        if c == 'C':
            x, y = self.checkAhead('M')
            self.pngs['M']['coins'] -= 1
            if not self.pngs['M']['coins']:
                self.field[x][y] = ' '
        elif c == 'H':
            assert self.h < 3
            self.h = 3
        elif c == 'K':
            x, y = self.checkAhead('|-')
            self.field[x][y] = ' '

    def attack(self):
        x, y = nmy = self.checkAhead('ED')
        self.pngs[nmy]['h'] -= self.atk
        if self.pngs[nmy]['h'] < 1:
            del self.pngs[nmy]
            self.field[x][y] = ' '
            lvlUp, self.xps = divmod(self.xps + 1, 3)
            self.atk += lvlUp

    def checkDmgsAndAlive(self):
        for dx, dy in list(self.DIRS.values()):
            nmy = (self.x + dx, self.y + dy)
            if nmy in self.pngs:
                self.h -= max(0, self.pngs[nmy]['atk'] - self.d)
                assert self.h > 0

def knights_tour(start, size):
    MOVES = [(-2, 2), (-2, -1), (-1, -2), (1, -2), (2, -1), (2, 1), (1, 2), (-1, 2)]

    def genNeighs(pos):
        return ((pos[0] + dx, pos[1] + dy) for dx, dy in MOVES if (pos[0] + dx, pos[1] + dy) in Warnsdorf_DP)

    def travel(pos):
        neighs = sorted(((Warnsdorf_DP[n], n) for n in genNeighs(pos)))
        for nSubNeighs, neigh in neighs:
            del Warnsdorf_DP[neigh]
            path.append(neigh)
            subNeighs = list(genNeighs(neigh))
            for n in subNeighs:
                Warnsdorf_DP[n] -= 1
            travel(neigh)
            if not Warnsdorf_DP:
                break
            else:
                for n in subNeighs:
                    Warnsdorf_DP[n] += 1
                Warnsdorf_DP[path.pop()] = nSubNeighs
    path, Warnsdorf_DP = ([start], {(x, y): 0 for x in range(size) for y in range(size) if (x, y) != start})
    for pos in Warnsdorf_DP:
        Warnsdorf_DP[pos] = sum((1 for _ in genNeighs(pos)))
    travel(start)
    return path

