class Graph:

    def __init__(self, vertices_num):
        self.v = vertices_num

    def adjmat_2_graph(self, adjm):
        d = {f'A{i}': [] for i in range(self.v)}
        for i, j in enumerate(adjm):
            for k, l in enumerate(j):
                if l:
                    d[f'A{i}'].append((f'A{k}', l))
        return d

    def graph_2_mat(self, graph):
        mat = [[0 for _ in range(self.v)] for _ in range(self.v)]
        for i, j in graph.items():
            for k, l in j:
                mat[int(i[1])][int(k[1])] = l
        return mat

    def graph_2_list(self, graph):
        return [[i, j] for i, j in sorted(graph.items())]

    def list_2_graph(self, lst):
        return {i: x for i, x in lst}

    def mat_2_list(self, mat):
        return self.graph_2_list(self.adjmat_2_graph(mat))

    def list_2_mat(self, lst):
        return self.graph_2_mat(self.list_2_graph(lst))

    def find_all_paths(self, graph, start, end):
        graph = {i: [k[1] for k in j] for i, j in graph.items()}
        Q, paths = (deque([[start, []]]), [])
        while Q:
            node, path = Q.popleft()
            path.append(node)
            if node == end:
                paths.append('-'.join(path))
            for n in graph[node]:
                if n not in path:
                    Q.append([n, path[:]])
        return sorted(paths, key=len)

def get(cells, i, j):
    return cells[i][j] if i > -1 and j > -1 and (i < len(cells)) and (j < len(cells[0])) else 0

def num_neighbors(cells, i, j):
    return get(cells, i, j + 1) + get(cells, i, j - 1) + get(cells, i + 1, j) + get(cells, i - 1, j) + get(cells, i - 1, j - 1) + get(cells, i - 1, j + 1) + get(cells, i + 1, j - 1) + get(cells, i + 1, j + 1)

def next_cell(cell, i, j):
    n = num_neighbors(cell, i, j)
    return int(0 if n < 2 or n > 3 else 1 if cell[i][j] else n == 3)

def expand(cells):
    row = [0] * (len(cells[0]) + 2)
    return [row] + [[0] + r + [0] for r in cells] + [row]

def trim(cells):
    while not any(cells[0]):
        del cells[0]
    while not any(cells[-1]):
        del cells[-1]
    while not any([row[0] for row in cells]):
        list(map(lambda x: x.pop(0), cells))
    while not any([row[-1] for row in cells]):
        list(map(lambda x: x.pop(), cells))

def next_gen(cells):
    cells = expand(cells)
    cells = [[next_cell(cells, i, j) for j in range(len(cells[i]))] for i in range(len(cells))]
    trim(cells)
    return cells

def get_generation(cells, generations):
    for i in range(generations):
        cells = next_gen(cells)
    if not cells:
        return [[]]
    return cells

class Solution:

    def rearrangeBarcodes(self, barcodes: List[int]) -> List[int]:
        if len(barcodes) < 2:
            return barcodes
        sorted_codes = sorted(barcodes)
        halfway = len(barcodes) // 2
        ans = [0] * (halfway * 2)
        ans[::2], ans[1::2] = (sorted_codes[-halfway:], sorted_codes[:halfway])
        if len(barcodes) % 2 == 1:
            prev = None
            mid = sorted_codes[halfway]
            for i in range(len(ans) - 1):
                if ans[i] == mid:
                    i += 1
                elif ans[i] != prev:
                    ans.insert(i, mid)
                    break
                prev = ans[i]
        return ans

class Solution:

    def numsSameConsecDiff(self, n: int, k: int) -> List[int]:
        if n == 1:
            return [i for i in range(10)]
        queue = [digit for digit in range(1, 10)]
        for level in range(n - 1):
            next_queue = []
            for num in queue:
                tail_digit = num % 10
                next_digits = set([tail_digit + k, tail_digit - k])
                for next_digit in next_digits:
                    if 0 <= next_digit < 10:
                        new_num = num * 10 + next_digit
                        next_queue.append(new_num)
            queue = next_queue
        return queue

