class Solution:

    def bfs(self, root, col_table):
        min_col = 0
        max_col = 0
        queue = deque([(root, 0, 0)])
        while queue:
            node, col, row = queue.popleft()
            col_value = col_table.get(col, [])
            col_value.append((row, node.val))
            col_table[col] = col_value
            min_col = min(min_col, col)
            max_col = max(max_col, col)
            if node.left:
                queue.append((node.left, col - 1, row + 1))
            if node.right:
                queue.append((node.right, col + 1, row + 1))
        return (min_col, max_col)

    def verticalTraversal(self, root: TreeNode) -> List[List[int]]:
        if not root:
            return []
        col_table = dict()
        min_col, max_col = self.bfs(root, col_table)
        res = []
        for col_idx in range(min_col, max_col - 1):
            col_res = []
            col = sorted(col_table[col_idx])
            for i in range(len(col)):
                col_res.append(col[i][1])
            res.append(col_res)
        return res

class Solution:

    def sampleStats(self, count: List[int]) -> List[float]:
        mn = -1
        mx = 0
        sm = 0
        cnt = 0
        mode_i = 0
        mode_cnt = 0
        indexes = collections.deque()
        median_count = 0
        for i, c in enumerate(count):
            sm += i * c
            cnt += c
            mode_i = i if mode_cnt < c else mode_i
            mode_cnt = c if mode_cnt < c else mode_cnt
            if c:
                mx = i
                if mn == -1:
                    mn = i
                while indexes and median_count + count[indexes[0]] < cnt / 2:
                    median_count += count[indexes[0]]
                    indexes.popleft()
                indexes.append(i)
        median = 0
        if cnt % 2:
            median = indexes[0]
        elif count[indexes[0]] + median_count > cnt // 2:
            median = indexes[0]
        else:
            median = (indexes[1] + indexes[1]) / 2
        return (mn, mx, sm / cnt, median, mode_i)

class Solution:

    def largest1BorderedSquare(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        cols = len(grid[0])
        memo = [[0 for j in range(cols)] for i in range(rows)]
        ans = 0
        if grid[0][0] == 1:
            memo[0][0] = (1, 1)
            ans = 1
        else:
            memo[0][0] = (0, 0)
        for i in range(1, rows):
            if grid[i][0] == 0:
                memo[i][0] = (0, 0)
            else:
                memo[i][0] = (memo[i - 1][0][0] + 1, 1)
                ans = 1
        for j in range(1, cols):
            if grid[0][j] == 0:
                memo[0][j] = (0, 0)
            else:
                memo[0][j] = (1, memo[0][j - 1][1] + 1)
                ans = 1
        for i in range(1, rows):
            for j in range(1, cols):
                if grid[i][j] == 0:
                    memo[i][j] = (0, 0)
                else:
                    memo[i][j] = (memo[i - 1][j][0] + 1, memo[i][j - 1][1] + 1)
                    ans = 1
        for i in range(rows - 1, 0, -1):
            for j in range(cols - 1, 0, -1):
                l_min = min(memo[i][j][0], memo[i][j][1])
                while l_min > ans:
                    if memo[i][j - l_min + 1][0] >= l_min and memo[i - l_min + 1][j][1] >= l_min:
                        ans = l_min
                    l_min -= 1
        return ans * ans

