        if q == 1:
            segments[i - 1][0] += a
        else:
            segments[i - 1][1] -= a
        arm.modify(i - 1, (degrect(segments[i - 1][0], segments[i - 1][1]), segments[i - 1][1]))
        query = arm.query(0, n)[0]
        print(query.real, query.imag)
