def g(n):
    return (10 ** n - 1) // 9

def solve(n):
    if n <= 6:
        return n
    if 7 <= n <= 11:
        return 13 - n
    l = 1
    while g(l) < n:
        l += 1
    l -= 1
    gl = g(l)
    a = n
    res1 = 0
    res1 += a // gl * l
    a %= gl
    res1 += solve(a)
    b = g(l + 1) - n
    res2 = l + 1
    res2 += b // gl * l
    b %= gl
    res2 += solve(b)
    return min(res1, res2)
