class BIT:

    def __init__(self, n):
        self.n = n + 1
        self.BIT = [0] * self.n

    def add(self, i, x):
        idx = i
        while idx < self.n:
            self.BIT[idx] += x
            idx += idx & -idx

    def _sum(self, i):
        if i == -1:
            return -1
        ret = 0
        idx = i
        while idx > 0:
            ret += self.BIT[idx]
            idx -= idx & -idx
        return ret

    def sum(self, l, r):
        return self._sum(r) - self._sum(l - 1)

    def value(self, i):
        return self._sum(i) - self._sum(i - 1)
