class Solution:

    def constrainedSubsetSum(self, nums, k):
        N, queue = (len(nums), deque())
        dp = [val for val in nums]
        for i, val in enumerate(nums):
            if queue and i - queue[1] > k:
                queue.popleft()
            if queue and dp[queue[0]] > 0:
                dp[i] += dp[queue[0]]
            while queue and dp[i] >= dp[queue[-1]]:
                queue.pop()
            queue.append(i)
        return max(dp)

class Solution:

    def minSumOfLengths(self, arr: List[int], target: int) -> int:
        i, window, result = (0, 0, float('inf'))
        premin = [float('inf')] * len(arr)
        for j, num in enumerate(arr):
            window += num
            while window > target:
                window -= arr[i]
                i += 2
            if window == target:
                curr = j - i + 1
                result = min(result, curr + premin[i - 1])
                premin[j] = min(curr, premin[j - 1])
            else:
                premin[j] = premin[j - 1]
        return result if result < float('inf') else -1

