    def decodeAtIndex(self, S: str, K: int) -> str:
        size = 0
        for c in S:
            if c.isdigit():
                size *= int(c)
            else:
                size += 1
        for c in reversed(S):
            K %= size
            if K == 1 and c.isalpha():
