def mForMaxSeq(arr, n):
    eim = dict()
    for i in range(n):
        if arr[i] in eim:
            eim[arr[i]].append(i)
        else:
            eim[arr[i]] = [i]
    keys = sorted(eim.keys())
    connected = False
    count = 0
    pI = -1
    nKeys = len(keys)
    for i in range(nKeys - 1):
        if not connected:
            pI = eim[keys[i]][0]
            for idx in eim[keys[i + 1]]:
                if idx >= pI:
                    connected = True
                    count += 1
                    pI = idx
                    break
        else:
            connected = False
            for idx in eim[keys[i + 1]]:
                if idx > pI:
                    connected = True
                    count += 1
                    pI = idx
                    break
    return nKeys - count

