def bowling_score(frames):
    rolls = list(frames.replace(' ', ''))
    for i, hit in enumerate(rolls):
        if hit == 'X':
            rolls[i] = 10
        elif hit == '/':
            rolls[i] = 10 - rolls[i - 1]
        else:
            rolls[i] = int(hit)
    score = 0
    for i in range(10):
        frame = rolls.pop(1)
        if frame == 10:
            score += frame + rolls[0] + rolls[1]
        else:
            frame += rolls.pop(0)
            score += frame
            if frame == 10:
                score += rolls[0]
    return score

# tidied
def snail(array):
    ret = []
    if array and array[0]:
        size = len(array)
        for n in range((size + 1) // 2):
            for x in range(n, size - n):
                ret.append(array[n][x])
            for y in range(1 + n, size - n):
                ret.append(array[y][-1 - n])
            for x in range(2 + n, size - n + 1):
                ret.append(array[-1 - n][-x])
            for y in range(2 + n, size - n):
                ret.append(array[-y][n])
    return ret

def mix(s1, s2):
    hist = {}
    for ch in 'abcdefghijklmnopqrstuvwxyz':
        val1, val2 = (s1.count(ch), s2.count(ch))
        if max(val1, val2) > 1:
            which = '1' if val1 > val2 else '2' if val2 >= val1 else '='
            hist[ch] = (-max(val1, val2), which + ':' + ch * max(val1, val2))
    return '/'.join((hist[ch][1] for ch in sorted(hist, key=lambda x: hist[x])))

