class Warrior:

    def __init__(self):
        self._experience = 100
        self.rs = ['Pushover', 'Novice', 'Fighter', 'Warrior', 'Veteran', 'Sage', 'Elite', 'Conqueror', 'Champion', 'Master', 'Greatest']
        self.achievements = []

