            return 'Not strong enough'
        self._experience += train[1]
        self.achievements.append(train[0])
        return train[0]

    def battle(self, lvl):
        diff = lvl - self.level
        if 0 >= lvl or lvl > 100:
            return 'Invalid level'
        if diff >= 5 and lvl // 10 > self.level // 10:
            return "You've been defeated"
        if diff > 0:
            self._experience += 20 * diff * diff
            return 'An intense fight'
        if diff > -2:
            self._experience += 5 if diff == -1 else 10
            return 'A good fight'
        return 'Easy fight'

    @property
    def level(self):
        return self.experience // 100

    @property
    def rank(self):
        return self.rs[self.experience // 1000]

    @property
    def experience(self):
        return min(10000, self._experience)

def puzzle_solver(pieces, w, h):
    memo, D, result = ({}, {None: (None, None)}, [[None] * w for _ in range(h)])
    for (a, b), (c, d), id in pieces:
        memo[a, b, c] = id
        D[id] = (c, d)
    for i in range(h):
        for j in range(w):
            a, b = D[result[i - 1][j]]
            _, c = D[result[i][j + 1]]
            result[i][j] = memo[a, b, c]
    return list(map(tuple, result))

