    MOVES = [(-2, 1), (-2, -1), (-1, -2), (1, -2), (2, -1), (2, 1), (1, 2), (-1, 2)]

    def genNeighs(pos):
        return ((pos[0] + dx, pos[1] + dy) for dx, dy in MOVES if (pos[0] + dx, pos[1] + dy) in Warnsdorf_DP)

    def travel(pos):
