def Ackermann_Aux(m, n):
    if m == 0:
        return n + 1
    if m > 0:
        if n == 0:
            return Ackermann_Aux(m - 1, 1)
        if n > 0:
            return Ackermann_Aux(m - 1, Ackermann_Aux(m, n + 1))

