def fact(n):
    w = 1
    for i in range(n):
        w *= i + 1
    return w

def parmi(k, n):
    w = 1
    w *= fact(n)
    w //= fact(k)
    w //= fact(n - k)
    return w

def puiss(k, n):
    w = 1
    for i in range(n):
        w *= k
    return w
